        16 => ["bintang" => "Surtan", "balaBantuan" => "Arab", "musuh" => "Dalu", "sumber" => "Pemarah, cemburuan, keras bicaranya, dengan bentuk badan sedang dan warna kulit kuning agak kehijauan.", "kesaktian" => "Dalam sumber dikaitkan dengan cincin bermata hijau.", "syarat" => "Memakai cincin bermata hijau.", "kejayaan" => "Hari Rabu — bulan Syawal.", "kemalangan" => "Hari Ahad — bulan Jumadilawal.", "penyakit" => "Dalam sumber disebut pernah jatuh sakit pada usia tujuh bulan.", "makna" => "Menurut Primbon Jawa, Bintang Surtan digambarkan membawa perasaan yang kuat dan cara bicara yang tegas. Tenaga seperti ini dapat membantu seseorang bersikap jujur terhadap keadaan, meski perlu disertai ruang untuk mendengar dan menenangkan diri. Dalam tradisi ini, kelembutan bukan lawan dari ketegasan, melainkan penyeimbang yang membuat kekuatan lebih bermanfaat."],
        17 => ["bintang" => "Sada", "balaBantuan" => "Arab", "musuh" => "Mijan", "sumber" => "Sopan santun, sabar, ikhlas hatinya, manis tutur katanya, dan giat bekerja. Akan mendapatkan pertolongan pada hari yang akan datang.", "kesaktian" => "Api di dekat musuh; dalam sumber juga disebut uap beracun dan pertolongan dari wanita yang memberi makan.", "syarat" => "Memakai cincin bermata merah.", "kejayaan" => "Hari Ahad — bulan Jumadilawal.", "kemalangan" => "Hari Sabtu — bulan Besar.", "penyakit" => "Perut.", "makna" => "Menurut Primbon Jawa, Bintang Sada menggambarkan pribadi yang mengutamakan kesabaran, ketulusan, dan tutur kata yang manis. Kegigihan dalam bekerja disebut sebagai bagian penting dari perjalanannya, bersama keyakinan bahwa pertolongan dapat datang pada waktunya. Tradisi ini menempatkan ketabahan sebagai kekuatan yang tumbuh perlahan, bukan sekadar hasil yang datang seketika."],
